(()=>{'use strict';const URL='search-index-lite.json?v=20261017-joker-coach-v1';const TEAM_URL='ffws-br-2026-s2/teams.json?v=20260922-inf-v32';let items=[],promise=null;const live=new Map(),livePending=new Map(),CAREER_API='https://cff-camp-notifications.nakataffb4.workers.dev/careers/search';const currentTeams=new Set(['AFROGAMES','ALPHA7','CIVIS','CPT VOX','FLUXO W7M','INFLUENCE RAGE','INTZ','LOOPS','LOS','LOUD SNICKERS','RISE GAMING','RUSH GAMING','SX TET','TEAM SOLID']);const cache=new Map;const timers={};const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function prepare(raw){return(raw||[]).map(x=>({...x,_search:norm([x.title,x.sub,...(x.aliases||[])].join(' ')),_title:norm(x.title)}))}function load(){if(items.length)return Promise.resolve(items);if(promise)return promise;promise=fetch(URL,{cache:'default'}).then(r=>{if(!r.ok)throw new Error('Busca indisponível');return r.json()}).then(d=>items=prepare(d.items||[])).catch(()=>items=[]);return promise}function newsItems(){const list=window.CFF_NOTICIAS_CACHE||window.cffNoticias||window.__CFF_NOTICIAS||[];return list.slice(0,80).map((n,i)=>({type:'news',id:n.urlInterna||n.link_original||n.id||String(i),title:n.titulo||'Notícia',sub:n.data?`Notícia • ${n.data}`:'Notícia',image:n.imagem||'central free fire.webp',url:n.urlInterna||n.link_original||'#',_search:norm([n.titulo,n.resumo,n.autor].join(' ')),_title:norm(n.titulo)}))}function score(x,q,tokens){if(x._title===q)return 1000;if(x._title.startsWith(q))return 850;if(x._search.startsWith(q))return 760;if(x._search.includes(q))return 620;let hit=0;for(const t of tokens)if(x._search.includes(t))hit++;return hit===tokens.length?420+hit*10:-1}
function careerResults(query){
 const q=norm(query);if(q.length<2)return Promise.resolve();
 const stored=live.get(q);if(stored&&Date.now()-stored.at<20000)return Promise.resolve();
 if(livePending.has(q))return livePending.get(q);
 const job=fetch(CAREER_API+'?query='+encodeURIComponent(query),{cache:'no-store',signal:AbortSignal.timeout(6000)})
 .then(r=>{if(!r.ok)throw Error('Busca de carreiras indisponível');return r.json()})
 .then(data=>{
  const rows=(data.entries||[]).map(p=>{
   const title=String(p.name||''),status=p.status==='free_agent'?'Sem equipe / F/A':p.status==='retired'?'Aposentado':p.team||'Equipe a confirmar',
    role=p.kind==='staff'?({'analyst':'Analista','coach':'Coach','head_coach':'Head coach','assistant_coach':'Assistente técnico','manager':'Manager'}[p.role]||'Comissão técnica'):'';
   const sub=[status,role].filter(Boolean).join(' · '),id=String(p.id||''),url='/'+(p.kind==='staff'||id.startsWith('person-')?'carreira.html':'jogador.html')+'?id='+encodeURIComponent(id);
   return {type:p.kind==='staff'?'staff':'player',id,title,sub,image:p.photo||'silhueta.webp',url,_live:true,_search:norm([title,sub].join(' ')),_title:norm(title)};
  }).filter(row=>row.id&&row.title);
  live.set(q,{at:Date.now(),items:rows});while(live.size>24)live.delete(live.keys().next().value);
 }).catch(()=>{}).finally(()=>livePending.delete(q));
 livePending.set(q,job);return job;
}
function find(q){
 q=norm(q);if(q.length<2)return[];
 const tokens=q.split(' ').filter(Boolean),old=items.concat(newsItems()),updated=live.get(q)?.items||[],
 ids=new Set(updated.map(x=>x.id)),names=new Set(updated.map(x=>x.type+':'+norm(x.title))),
 all=updated.concat(old.filter(x=>!((x.type==='player'||x.type==='staff')&&(ids.has(x.id)||names.has(x.type+':'+norm(x.title))))));
 return all.map(x=>({x,s:score(x,q,tokens)+(x._live?10:0)})).filter(v=>v.s>=0)
 .sort((a,b)=>b.s-a.s||a.x.title.localeCompare(b.x.title,'pt-BR')).slice(0,20).map(v=>v.x);
}function teamUrl(name){const team=String(name||'').trim(),canonical=team.toUpperCase()==='LOUD'?'LOUD SNICKERS':team.toUpperCase();return currentTeams.has(canonical)?'/equipe/'+canonical.toLowerCase().replace(/[^a-z0-9]+/g,'-'):`equipe-historica.html?time=${encodeURIComponent(team)}`}function action(item){if(item._live&&item.url)location.href=item.url;else if(item.type==='player')location.href=`jogador.html?id=${encodeURIComponent(item.id)}`;else if(item.type==='team')location.href=teamUrl(item.title);else if(item.type==='news')location.href=item.url||'#';else if(item.url)location.href=item.url;else window.navigate?.(item.id)}function row(x){return`<button type="button" class="search-item cff-fast-search-item" data-fast-type="${esc(x.type)}" data-fast-id="${esc(x.id)}"><img src="${esc(x.image||'silhueta.webp')}" onerror="this.onerror=null;this.src='${x.type==='team'?'escudo.webp':'silhueta.webp'}'" alt=""><span class="cff-fast-search-copy"><strong>${esc(x.title)}</strong><small>${esc(x.sub||'')}</small></span></button>`}function render(source){const input=document.getElementById(source==='desktop'?'global-search-desktop':source==='mobile'?'global-search-mobile':'global-search-page-input');const box=document.getElementById(source==='desktop'?'search-results-desktop':source==='mobile'?'search-results-mobile':'global-search-results-container');if(!input||!box)return;const q=input.value.trim();if(q.length<2){if(source==='page')box.innerHTML='<div class="global-search-empty">Digite pelo menos 2 caracteres para pesquisar.</div>';else box.style.display='none';return}const results=find(q);if(source==='page'){box.innerHTML=results.length?`<div class="global-search-summary">${results.length} resultado(s)</div><div class="global-search-grid">${results.map(row).join('')}</div>`:'<div class="global-search-empty">Nenhum resultado encontrado.</div>'}else{box.innerHTML=results.slice(0,8).map(row).join('')||'<div style="padding:15px;color:#888;text-align:center">Nenhum resultado encontrado.</div>';box.style.display='block'}}function from(source){clearTimeout(timers[source]);clearTimeout(timers['live:'+source]);
 timers[source]=setTimeout(()=>load().then(()=>render(source)),90);
 timers['live:'+source]=setTimeout(()=>{
 const el=document.getElementById(source==='desktop'?'global-search-desktop':source==='mobile'?'global-search-mobile':'global-search-page-input');
 const query=el?.value.trim()||'';if(norm(query).length<2)return;
 careerResults(query).then(()=>{if(el?.value.trim()===query)render(source);});
},350)}function bind(){[['global-search-desktop','desktop'],['global-search-mobile','mobile'],['global-search-page-input','page']].forEach(([id,source])=>{const input=document.getElementById(id);if(!input||input.dataset.fastBound)return;input.dataset.fastBound='1';input.removeAttribute('oninput');input.addEventListener('input',()=>from(source));input.addEventListener('focus',load,{once:true})});['search-results-desktop','search-results-mobile','global-search-results-container'].forEach(id=>{const box=document.getElementById(id);if(!box||box.dataset.fastBound)return;box.dataset.fastBound='1';box.addEventListener('click',e=>{const btn=e.target.closest('[data-fast-id]');if(!btn)return;const item=[...live.values()].flatMap(v=>v.items).find(x=>x.type===btn.dataset.fastType&&String(x.id)===btn.dataset.fastId)||items.concat(newsItems()).find(x=>x.type===btn.dataset.fastType&&String(x.id)===btn.dataset.fastId);if(item)action(item)})});document.addEventListener('click',e=>{if(!e.target.closest('.search-container,.nav-search-wrapper,#mobile-search-bar,.global-search-page')){document.getElementById('search-results-desktop')?.style.setProperty('display','none');document.getElementById('search-results-mobile')?.style.setProperty('display','none')}})}function teamNav(){fetch(TEAM_URL,{cache:'default'}).then(r=>r.ok?r.json():{teams:[]}).then(d=>{const root=document.getElementById('nav-desktop-teams');if(!root)return;const teams=(d.teams||[]).map(t=>({title:t.name,image:t.logo||'escudo.webp'}));teams.forEach(t=>currentTeams.add(String(t.title||'').toUpperCase()));root.innerHTML=teams.map(t=>`<button class="nav-team-logo-btn" type="button" title="${esc(t.title)}" data-fast-team="${esc(t.title)}"><img src="${esc(t.image)}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'" alt="${esc(t.title)}"></button>`).join('');if(!root.dataset.fastTeamBound){root.dataset.fastTeamBound='1';root.addEventListener('click',e=>{const b=e.target.closest('[data-fast-team]');if(b)location.href=teamUrl(b.dataset.fastTeam)})}}).catch(()=>{})}function toggleTeams(event){event?.preventDefault();event?.stopPropagation();const drop=document.getElementById('teams-drop');if(!drop)return;drop.classList.toggle('active')}window.toggleTeams=toggleTeams;document.addEventListener('click',e=>{const drop=document.getElementById('teams-drop');if(drop?.classList.contains('active')&&!e.target.closest('.nav-teams-wrapper'))drop.classList.remove('active')});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('teams-drop')?.classList.remove('active')});window.cffFastSearchFrom=from;window.handleGlobalSearchFrom=from;window.cffRestoreFastSearch=function(){window.handleGlobalSearchFrom=from;window.cffFastSearchFrom=from;bind()};window.openCurrentSeasonPlayer=(name,team='')=>location.href=`jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(team)}`;window.openCurrentSeasonTeam=name=>location.href=teamUrl(name);function idlePreload(){const run=()=>load();if('requestIdleCallback'in window)requestIdleCallback(run,{timeout:3500});else setTimeout(run,2200)}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',()=>{bind();teamNav();idlePreload()},{once:true}):(bind(),teamNav(),idlePreload())})();
